import React,{useState} from 'react';
import { mockProducts,formatMoney,mockCategories } from '../../lib/api';
const statuses=['pendente','confirmado','em_producao','pronto','enviado','entregue'];
export function Dashboard(){const cards=[['Vendas do mês','R$ 28.450,00'],['Pedidos do mês','184'],['Ticket médio','R$ 154,61'],['Clientes novos','72'],['Produtos em estoque','3.000'],['Pedidos pendentes','18']];return <AdminPage title="Dashboard"><div className="grid md:grid-cols-3 gap-5">{cards.map(([a,b])=><div className="card p-6"><p className="text-gray-500">{a}</p><b className="text-3xl text-primary">{b}</b></div>)}</div><div className="grid lg:grid-cols-2 gap-6 mt-6"><Panel title="Vendas por período"/><Panel title="Status dos pedidos"/></div></AdminPage>}
export function Produtos(){return <AdminPage title="Gerenciador de Produtos"><button className="btn btn-primary mb-5">Novo Produto</button><Table heads={['Imagem','Nome','Categoria','Preço','Estoque','Status','Ações']} rows={mockProducts.map(p=>[<img src={p.imagem_principal} className="w-14 h-14 rounded-xl object-cover"/>,p.nome,p.categoria_nome,formatMoney(p.preco),p.estoque,p.estoque>0?'Ativo':'Inativo','Editar · Deletar · Ver'])}/></AdminPage>}
export function Pedidos(){return <AdminPage title="Gerenciador de Pedidos"><ManualOrderForm/><h2 className="font-display text-2xl text-primary mt-8 mb-4">Pedidos registrados</h2><Table heads={['Número','Cliente','Origem','Data','Status','Total','Ações']} rows={Array.from({length:8},(_,i)=>[`WC${Date.now()+i}`,'Cliente '+(i+1),i%2?'WhatsApp':'Manual',new Date().toLocaleDateString('pt-BR'),statuses[i%statuses.length],formatMoney(120+i*35),'Ver · Atualizar · Recibo · Etiqueta'])}/></AdminPage>}
function ManualOrderForm(){const [open,setOpen]=useState(false);return <div className="card p-6"><div className="flex justify-between gap-4 items-center"><div><h2 className="font-display text-2xl text-primary">Registrar pedido manualmente</h2><p className="text-gray-600 mt-1">Use para controlar pedidos fechados no balcão, WhatsApp ou telefone.</p></div><button className="btn btn-primary" onClick={()=>setOpen(!open)}>{open?'Fechar':'Novo pedido manual'}</button></div>{open&&<form className="grid md:grid-cols-3 gap-4 mt-6"><input className="input" placeholder="Nome do cliente"/><input className="input" placeholder="Telefone"/><input className="input" placeholder="Email opcional"/><input className="input md:col-span-2" placeholder="Descrição do pedido"/><input className="input" placeholder="Total R$"/><select className="input"><option>pendente</option><option>confirmado</option><option>em_producao</option><option>pronto</option><option>entregue</option></select><select className="input"><option>Pagamento pendente</option><option>Pagamento confirmado</option></select><button type="button" className="btn btn-primary">Salvar pedido manual</button><button type="button" className="btn btn-outline">Gerar recibo</button></form>}</div>}
export function Clientes(){return <AdminPage title="Gerenciador de Clientes"><Table heads={['Nome','Email','Telefone','Total gasto','Pedidos','Cadastro','Ações']} rows={Array.from({length:7},(_,i)=>[`Cliente ${i+1}`,`cliente${i+1}@email.com`,'(88) 99624-0470',formatMoney(450+i*120),i+2,new Date().toLocaleDateString('pt-BR'),'Ver · Editar'])}/></AdminPage>}
export function Categorias(){return <AdminPage title="Gerenciador de Categorias"><button className="btn btn-primary mb-5">Nova Categoria</button><Table heads={['Nome','Slug','Produtos','Status','Ações']} rows={mockCategories.map((c,i)=>[c.nome,c.slug,12+i,'Ativo','Editar · Deletar'])}/></AdminPage>}
export function Cupons(){return <AdminPage title="Gerenciador de Cupons"><button className="btn btn-primary mb-5">Novo Cupom</button><Table heads={['Código','Tipo','Valor','Uso','Datas','Status','Ações']} rows={['PRIMEIRA10','FRETE15','GRAFICA20'].map((c,i)=>[c,i===1?'fixo':'percentual',i===1?'R$ 15':'10%','3/100','01/01 até 31/12','Ativo','Editar · Desativar'])}/></AdminPage>}
export function Avaliacoes(){return <AdminPage title="Gerenciador de Avaliações"><Table heads={['Produto','Cliente','Nota','Comentário','Verificado','Data','Ações']} rows={mockProducts.slice(0,5).map((p,i)=>[p.nome,'Cliente '+(i+1),'★★★★★','Excelente qualidade','Sim',new Date().toLocaleDateString('pt-BR'),'Responder · Rejeitar'])}/></AdminPage>}
export function Configuracoes(){const tabs=['Informações Gerais','Sobre','Frete','Redes Sociais','Email','WhatsApp','Políticas'];return <AdminPage title="Configurações do Site"><div className="grid lg:grid-cols-4 gap-6"><div className="card p-4 grid gap-2">{tabs.map(t=><button className="text-left px-4 py-3 rounded-xl hover:bg-gray-100 font-bold">{t}</button>)}</div><form className="card p-6 lg:col-span-3 grid md:grid-cols-2 gap-4"><input className="input" defaultValue="Gráfica W Criações"/><input className="input" defaultValue="contato@graficawcriacoes.com"/><input className="input" defaultValue="(88) 99624-0470"/><input className="input" defaultValue="5588996240470"/><textarea className="input md:col-span-2 min-h-32" defaultValue="Finalização de pedidos pelo WhatsApp, sem pagamento online. Recibo disponível após conclusão do pedido."/><button className="btn btn-primary md:col-span-2">Salvar configurações</button></form></div></AdminPage>}
export function Contatos(){return <AdminPage title="Gerenciador de Contatos"><Table heads={['Nome','Email','Telefone','Assunto','Data','Status','Ações']} rows={Array.from({length:6},(_,i)=>[`Lead ${i+1}`,`lead${i+1}@email.com`,'(88) 99624-0470','Orçamento',new Date().toLocaleDateString('pt-BR'),i%2?'Respondido':'Pendente','Ver · Responder'])}/></AdminPage>}
export function Relatorios(){return <AdminPage title="Relatórios"><div className="grid md:grid-cols-2 gap-6"><Panel title="Relatório de vendas"/><Panel title="Produtos mais vendidos"/><Panel title="Clientes recorrentes"/><Panel title="Frete"/></div><button className="btn btn-primary mt-6">Exportar CSV/PDF</button></AdminPage>}
export function Usuarios(){return <AdminPage title="Gerenciador de Usuários"><Table heads={['Nome','Email','Role','Data cadastro','Ações']} rows={[[`Administrador`,'admin@graficawcriacoes.com','admin',new Date().toLocaleDateString('pt-BR'),'Editar'],['Cliente','cliente@email.com','user',new Date().toLocaleDateString('pt-BR'),'Editar']]}/></AdminPage>}
function AdminPage({title,children}:{title:string;children:React.ReactNode}){return <div className="fade"><h1 className="font-display text-4xl text-primary mb-6">{title}</h1>{children}</div>}
function Panel({title}:{title:string}){return <div className="card p-6"><h2 className="font-display text-2xl">{title}</h2><div className="h-56 mt-5 rounded-2xl bg-gradient-to-br from-gray-100 to-gray-200 grid place-items-center text-gray-500">Gráfico dinâmico</div></div>}
function Table({heads,rows}:{heads:string[];rows:any[][]}){return <div className="card overflow-auto"><table className="w-full text-sm"><thead className="bg-gray-50"><tr>{heads.map(h=><th className="text-left p-4">{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr className="border-t" key={i}>{r.map((c,j)=><td className="p-4" key={j}>{c}</td>)}</tr>)}</tbody></table></div>}
